const { useState } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const Search = () => {
  const [keyword, setKeyword] = useState('');

  return (
    <div>
      <label className="field" htmlFor="q">코스 검색</label>
      <input
        className="field__input"
        id="q"
        type="search"
        value={keyword}
        onChange={(event) => setKeyword(event.target.value)}
      />
      <p className="echo">{keyword === '' ? '전체 코스' : `검색어: ${keyword}`}</p>
      <p className="count">{keyword.length}글자</p>
      <div className="row">
        <button className="clear" type="button" onClick={() => setKeyword('')}>지우기</button>
      </div>
    </div>
  );
};

root.render(<Search />);
